mapper.select:
SELECT o.id, o.pay_code, o.user_id, o.only_code, o.status, o.total_amount, o.discount_amount, o.net_amount, o.begin_time, o.end_time, o.voucher_id, o.calc,
i.id AS item_id, i.rule_code, i.rule_name, i.unit_price, i.min_bill_duration, i.max_bill_duration, i.max_price, i.pay_code, i.only_code, i.only_code_port, i.total_duration, i.per_use_duration, i.per_use_start_time, i.create_time, i.update_time
FROM net_site_order o LEFT JOIN net_site_order_itemized i ON o.pay_code = i.pay_code WHERE o.pay_code = #{payCode}

SELECT nso.id AS orderId, nso.only_code AS onlyCode, nso.pay_code AS payCode, nso.status, nso.total_amount AS totalAmount, nso.discount_amount AS discountAmount, nso.net_amount AS netAmount, nso.begin_time AS beginTime, nso.end_time AS endTime, ns.name AS siteName, u.nickname, u.mobile, ba.addr_name AS addrName FROM net_site_order nso LEFT JOIN net_site ns ON nso.only_code = ns.only_code LEFT JOIN user u ON nso.user_id = u.id LEFT JOIN bluetooth_address ba ON ns.address_id = ba.id WHERE 1=1
AND nso.user_id = #{bean.userId}
AND ba.id = #{bean.addressId}
AND nso.status = #{bean.orderStatus}
AND nso.pay_code LIKE CONCAT('%', #{bean.payCode}, '%')
AND u.mobile LIKE CONCAT('%', #{bean.mobile}, '%')
AND nso.begin_time BETWEEN #{bean.startDate} AND #{bean.endDate}
ORDER BY nso.begin_time DESC
LIMIT #{page.pageSize} OFFSET #{page.offset}

SELECT COUNT(*)
FROM net_site_order nso
LEFT JOIN net_site ns ON nso.only_code = ns.only_code
LEFT JOIN user u ON nso.user_id = u.id
LEFT JOIN bluetooth_address ba ON ns.address_id = ba.id
WHERE 1 = 1

    AND nso.user_id = #{bean.userId}


    AND nso.pay_code like CONCAT('%', #{bean.payCode}, '%')


    AND ba.id = #{bean.addressId}


    AND nso.status = #{bean.orderStatus}


    AND u.mobile LIKE CONCAT('%', #{bean.mobile}, '%')


    AND nso.begin_time between #{bean.startDate} and #{bean.endDate}
